        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2))
        print(f"  saved {path}")
    elif cmd == "check":
        ref = json.loads((D / f"{sys.argv[2]}.json").read_text())
        cur = collect(cached=ref)
        print_report(f"{sys.argv[2]} vs current", stats(ref, cur))
    elif cmd == "compare":
        a = json.loads((D / f"{sys.argv[2]}.json").read_text())
        b = json.loads((D / f"{sys.argv[3]}.json").read_text())
        print_report(f"{sys.argv[3]} vs {sys.argv[2]}", stats(a, b))
    else:
        print(__doc__)
        sys.exit"    {'OVERALL':<14s} max {overall['max']:.6f}  mean {overall['mean']:.6f}")
    print(f"LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


